import java.io.*;
import java.util.*;

public class Main {
    static int mod = (int) (Math.pow(10, 9) + 7);

    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        long n = sc.nextInt();
        long m = sc.nextInt();

        if (m < n) {
            long temp = n;
            n = m;
            m = temp;
        }

        long result;
        if (n <= 2 && m <= 2) {
            result = 0;
        } else if (n == 1) {
            long x = m / 6;
            long y = m % 6;
            result = x * 6;
            if (y >= 4) {
                result += (y - 3) * 2;
            }
        } else if (n == 2) {
            result = n * m;
            if (m == 3) result = 4;
            else if (m == 7) result = 12;
        } else {
            result = (n * m / 2) * 2;
        }

        out.println(result);
        out.close();
    }

    static long pow(long a, long N) {
        if (N == 0) {
            return 1;
        } else if (N == 1) {
            return a;
        } else {
            long R = pow(a, N / 2);
            if (N % 2 == 0) {
                return R * R;
            } else {
                return R * R * a;
            }
        }
    }

    static long powMod(long a, long N) {
        if (N == 0) {
            return 1;
        } else if (N == 1) {
            return a % mod;
        } else {
            long R = powMod(a, N / 2) % mod;
            R = (R * R) % mod;
            if (N % 2 == 1) {
                R = (R * (a % mod)) % mod;
            }
            return R % mod;
        }
    }

    static void mergeSort(int[] A) {
        int n = A.length;
        if (n < 2) return;
        int mid = n / 2;
        int[] l = new int[mid];
        int[] r = new int[n - mid];

        for (int i = 0; i < mid; i++) {
            l[i] = A[i];
        }
        for (int j = mid; j < n; j++) {
            r[j - mid] = A[j];
        }

        mergeSort(l);
        mergeSort(r);
        merge(l, r, A);
    }

    static void merge(int[] l, int[] r, int[] a) {
        int i = 0, j = 0, k = 0;

        while (i < l.length && j < r.length) {
            if (l[i] < r[j]) {
                a[k++] = l[i++];
            } else {
                a[k++] = r[j++];
            }
        }

        while (i < l.length) {
            a[k++] = l[i++];
        }
        while (j < r.length) {
            a[k++] = r[j++];
        }
    }

    public static PrintWriter out;

    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}
